'use client'

import * as React from 'react'

// The path is './reward' and not '../reward' on purpose: both items install
// into components/gamestage/<name>/, so this one specifier resolves the same in
// this repo and in a host application that ran `gamestage-ui add`.
import { Reward, type RewardPresentation, type RewardProps } from './reward'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Inventory, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './inventory.css'

/**
 * Inventory: everything a player has, in one place.
 *
 * Specimen 5b draws it: a title with the earned count across from it, a row of
 * filter pills, and a grid of compact `reward` cells with ghost cells for what
 * is still to be earned. It does not fetch the collection, does not sort it by
 * any rule of its own, does not paginate, does not filter and does not claim
 * anything. The host owns the list, its order and the filter in force; this
 * renders them and reports the presses: a filter pill through `onFilter`, a
 * cell through `onSelect`, after which the host opens whatever shows the
 * reward's detail.
 *
 * The case that matters is the one nobody builds: an inventory with nothing in
 * it. A new player opens this before they have won anything, so the empty case
 * is the first thing most players see, and a blank rectangle at that moment
 * reads as a component that failed to load. It carries
 * `data-gs-empty="true"`, it keeps the grid's shape with one row of ghosts, and
 * under them a card says what fills the grid and offers the one thing to do
 * about it. Its accessible name says so too.
 */

export interface InventoryFilter {
  id: string
  label: string
}

// `onSelect` is omitted from the DOM attributes for the reason reward omits it:
// it is the press on a cell, not the text-selection event of the same name.
export interface InventoryProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children' | 'onSelect'> {
  /** What this collection is: the title over the grid, and the group's accessible name. */
  label: string
  /**
   * The rewards, in the order the host wants them. An empty array is the empty
   * case and renders as one.
   */
  rewards?: RewardProps[]
  /**
   * How many rewards there are to earn in all. Renders the count across from
   * the title, `6 of 24`, and the ghost cells that complete the last row of
   * the grid. Without it there is no count and no ghost.
   */
  max?: number
  /**
   * The earned number in that count. Defaults to how many of `rewards` are
   * earned or claimed; a host whose count means something else says so.
   */
  earned?: number
  /**
   * The filters the host offers, drawn as a row of pills. The host applies
   * them: pressing one calls `onFilter` and changes nothing here.
   */
  filters?: InventoryFilter[]
  /** The id of the filter in force. */
  filter?: string
  /** The accessible name of the filter row. */
  filtersLabel?: string
  onFilter?: (id: string) => void
  /**
   * Which cell the grid holds: `compact` is specimen 5b's grid of square art
   * over a name, three or four to a row; `card` is specimen 3d's two-column
   * grid of full reward cards.
   */
  presentation?: Extract<RewardPresentation, 'compact' | 'card'>
  /**
   * The heading of the empty card, `Nothing yet`, and the sentence under it
   * that names the action and the next time. Host copy, both of them.
   */
  emptyLabel?: string
  emptyDetail?: React.ReactNode
  /** The one action on the empty card, and what pressing it does. Without a label there is no control. */
  emptyAction?: string
  onEmptyAction?: () => void
  /** Passed to every compact cell: the player pressed it, and the host opens its detail. */
  onSelect?: (id: string) => void
  /** Passed to every card, so one handler opens whichever one is waiting. */
  onReveal?: (id: string) => void
  /** Passed to every card, so one handler claims whichever one is earned and open. */
  onClaim?: (id: string) => void
}

/** The contract's word for `data-gs-empty`, in the accessible name. */
const EMPTY_NAME = 'nothing here yet'
const DEFAULT_EMPTY_LABEL = 'Nothing yet'
const DEFAULT_FILTERS_LABEL = 'Filter'

/**
 * The most ghost cells ever rendered: one row at the widest grid. The
 * stylesheet hides the ones that would start a new row, so the ghosts complete
 * the last row and stop, as the drawing draws them: two after seven cells at
 * three to a row, a whole row when there are none.
 */
const MAX_GHOSTS = 4

export function Inventory({
  label,
  rewards = [],
  max,
  earned,
  filters,
  filter,
  filtersLabel = DEFAULT_FILTERS_LABEL,
  onFilter,
  presentation = 'compact',
  emptyLabel = DEFAULT_EMPTY_LABEL,
  emptyDetail,
  emptyAction,
  onEmptyAction,
  onSelect,
  onReveal,
  onClaim,
  className,
  ...rest
}: InventoryProps) {
  const empty = rewards.length === 0

  // What it is, then how much of it there is. When there is none, the contract's
  // word rather than "0", because "0" is a count and this is an absence.
  const name = empty ? `${label}, ${EMPTY_NAME}` : `${label}, ${rewards.length}`

  const earnedCount =
    earned ?? rewards.filter((r) => r.state === 'earned' || r.state === 'claimed').length

  // The ghosts: what is still to earn, capped at one row. An empty inventory
  // keeps a row of them whatever `max` says, because the row is what keeps the
  // grid's shape under the card.
  const ghosts = empty
    ? max === undefined ? MAX_GHOSTS : Math.min(max, MAX_GHOSTS)
    : max === undefined ? 0 : Math.min(Math.max(max - rewards.length, 0), MAX_GHOSTS)

  return (
    <div
      {...rest}
      className={['gs-inventory', className].filter(Boolean).join(' ')}
      data-gs-component="inventory"
      data-gs-presentation={presentation}
      data-gs-empty={empty ? 'true' : undefined}
      // The count, machine-readable, beside whatever the collection renders.
      data-gs-value={rewards.length}
      role="group"
      aria-label={name}
    >
      {/* The title and, across from it, how many of the whole the player has.
          Both are read through the root's name, so they are hidden from it. */}
      <div className="gs-inventory__header" aria-hidden="true">
        <span className="gs-inventory__title" data-gs-scope="inventory" data-gs-part="label">
          {label}
        </span>
        {max !== undefined ? (
          <span className="gs-inventory__summary" data-gs-scope="inventory" data-gs-part="summary">
            <span className="gs-inventory__earned" data-gs-scope="inventory" data-gs-part="value">
              {earnedCount}
            </span>{' '}
            of {max}
          </span>
        ) : null}
      </div>

      {filters && filters.length > 0 ? (
        <div
          className="gs-inventory__filters"
          data-gs-scope="inventory" data-gs-part="actions"
          role="group"
          aria-label={filtersLabel}
        >
          {filters.map((f) => {
            const active = f.id === filter
            return (
              <button
                key={f.id}
                type="button"
                className="gs-inventory__filter"
                data-gs-scope="inventory" data-gs-part="control"
                data-gs-active={active ? 'true' : undefined}
                aria-pressed={active}
                onClick={() => onFilter?.(f.id)}
              >
                {f.label}
              </button>
            )
          })}
        </div>
      ) : null}

      {/* A real list, so a screen reader announces how many there are before
          reading them. The ghosts ride in it hidden: they are the grid's shape,
          not entries. In the empty case the list holds only ghosts and is
          hidden whole. */}
      <ul
        className="gs-inventory__list"
        data-gs-scope="inventory" data-gs-part="list"
        aria-hidden={empty ? 'true' : undefined}
      >
        {rewards.map((reward) => (
          <li className="gs-inventory__item" key={reward.id}>
            <Reward
              presentation={presentation}
              {...reward}
              onSelect={reward.onSelect ?? onSelect}
              onReveal={reward.onReveal ?? onReveal}
              onClaim={reward.onClaim ?? onClaim}
            />
          </li>
        ))}
        {Array.from({ length: ghosts }, (_, i) => (
          <li
            className="gs-inventory__slot"
            data-gs-scope="inventory" data-gs-part="slot"
            aria-hidden="true"
            key={`slot-${i}`}
          />
        ))}
      </ul>

      {empty ? (
        // A designed empty state, never a blank rectangle: what fills the grid,
        // when, and the one thing to do about it. Emphasis, not motion: there is
        // nothing here to animate, and the mark is the whole point.
        <div className="gs-inventory__empty" data-gs-scope="inventory" data-gs-part="empty">
          <span
            className="gs-inventory__glyph"
            data-gs-scope="inventory" data-gs-part="glyph"
            data-gs-animates="emphasis"
            aria-hidden="true"
          >
            ?
          </span>
          <span className="gs-inventory__empty-label" data-gs-scope="inventory" data-gs-part="label">
            {emptyLabel}
          </span>
          {emptyDetail ? (
            <span className="gs-inventory__empty-detail" data-gs-scope="inventory" data-gs-part="detail">
              {emptyDetail}
            </span>
          ) : null}
          {emptyAction ? (
            <button
              type="button"
              className="gs-inventory__commit gs-action-type gs-pressable"
              data-gs-scope="inventory" data-gs-part="commit"
              data-gs-next-action="true"
              data-gs-animates="motion"
              onClick={() => onEmptyAction?.()}
            >
              {emptyAction}
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

/* Inventory. Every value comes from a token; nothing here is a literal colour.

   Specimen 5b draws this, and design/twins/5b.json measures ours against it
   declaration by declaration: the header, the filter pills, the grid, the
   ghost cells and the empty card. The cells themselves are reward's compact
   presentation and are measured there. Where a value below is not the
   drawing's, the twins file says which token was the nearest and why.

   One value the drawing draws that no token carries: 6px, the gap between the
   filter pills and the space over the empty card's sentence. Composed from
   space.1 rather than written; a space.1-5 is a token request in the report. */

/* The collection has no surface of its own: the drawing draws the grid straight
   onto the page. */
.gs-inventory {
  --gs-inventory-gap-tight: calc(var(--gs-space-1) * 1.5);
  display: block;
  padding: 0;
  background: none;
  color: var(--gs-color-ink);
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
}

/* -- the header ----------------------------------------------------------- */
/* The title and the count on one baseline, the inset below them. */
.gs-inventory__header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-block-end: var(--gs-space-inset);
}

/* The title: the display face at the title size, uppercase, on the display
   shadow. Line height 1, as drawn, so the baseline the count shares is the
   glyphs' own. */
.gs-inventory__title {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: 1;
  text-transform: uppercase;
  text-shadow: var(--gs-type-display-shadow);
}

/* "6 of 24": the label type in the secondary ink, sentence case as drawn,
   with the earned number in the figure face and the reward colour. */
.gs-inventory__summary {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-ink-secondary);
}

.gs-inventory__earned {
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  color: var(--gs-color-reward-solid);
}

/* -- the filters ---------------------------------------------------------- */
/* A row of pills at 6, the inset below. Each pill is 32 tall: space.8 is the
   one token that is 32px, and a size.controlCompact for the drawing's small
   control (32px, fourteen uses) is a token request in the report. The current
   one sits on the interactive colour; the rest on the surface. */
.gs-inventory__filters {
  display: flex;
  gap: var(--gs-inventory-gap-tight);
  margin-block-end: var(--gs-space-inset);
}

.gs-inventory__filter {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  block-size: var(--gs-space-8);
  margin: 0;
  padding: 0 var(--gs-space-3);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-surface);
  color: var(--gs-color-ink-secondary);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: 1;
  cursor: pointer;
  /* Emphasis: the filter in force changes fill and ink, and a change a player
     only sees if they can see animation is not a change. */
  transition:
    background-color var(--gs-motion-emphasis) ease-out,
    color var(--gs-motion-emphasis) ease-out;
}

.gs-inventory__filter[data-gs-active='true'] {
  background: var(--gs-color-interactive);
  color: var(--gs-color-on-accent);
}

.gs-inventory__filter:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: var(--gs-space-1);
}

/* -- the grid ------------------------------------------------------------- */
/* Three to a row under 600px and four from it, at the drawing's 10px gutter.
   The card presentation keeps specimen 3d's two columns at 12. */
.gs-inventory__list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--gs-space-gap);
  margin: 0;
  padding: 0;
  list-style: none;
}

@media (min-width: 600px) {
  .gs-inventory__list { grid-template-columns: repeat(4, 1fr); }
}

.gs-inventory[data-gs-presentation='card'] .gs-inventory__list {
  grid-template-columns: repeat(2, 1fr);
  gap: var(--gs-space-3);
}

/* A cell stretches its reward, so a row of cells is a row and not a
   staircase when one is locked and its neighbour carries art. */
.gs-inventory__item { display: grid; }

/* -- the ghosts ----------------------------------------------------------- */
/* What is still to earn: the outline colour as the fill, a dashed muted
   outline at the cell's radius, fading across the row. A ghost in a row of
   cells stretches to the row; alone under the empty card it is a square, which
   is the drawing's 110px to within 3px at a phone width. A size for the cell
   itself is a token request in the report. */
.gs-inventory__slot {
  box-sizing: border-box;
  aspect-ratio: 1;
  border: var(--gs-stroke-ui) dashed var(--gs-color-muted);
  border-radius: var(--gs-radius-control);
  background: var(--gs-color-edge);
  opacity: 0.6;
}

.gs-inventory__slot + .gs-inventory__slot { opacity: 0.4; }
.gs-inventory__slot + .gs-inventory__slot + .gs-inventory__slot { opacity: 0.3; }

/* The ghosts complete the last row and stop. One that would start a new row
   is hidden, and so is every ghost after it. The empty case is the exception:
   its row is the grid's shape, so it keeps a whole row and fades from .7. */
@media (max-width: 599.98px) {
  .gs-inventory:not([data-gs-empty]) .gs-inventory__slot:nth-child(3n + 1),
  .gs-inventory:not([data-gs-empty]) .gs-inventory__slot:nth-child(3n + 1) ~ .gs-inventory__slot,
  .gs-inventory[data-gs-empty] .gs-inventory__slot:nth-child(n + 4) {
    display: none;
  }
}

@media (min-width: 600px) {
  .gs-inventory:not([data-gs-empty]) .gs-inventory__slot:nth-child(4n + 1),
  .gs-inventory:not([data-gs-empty]) .gs-inventory__slot:nth-child(4n + 1) ~ .gs-inventory__slot,
  .gs-inventory[data-gs-empty] .gs-inventory__slot:nth-child(n + 5) {
    display: none;
  }
}

.gs-inventory[data-gs-empty] .gs-inventory__slot { opacity: 0.7; }
.gs-inventory[data-gs-empty] .gs-inventory__slot + .gs-inventory__slot { opacity: 0.5; }
.gs-inventory[data-gs-empty] .gs-inventory__slot + .gs-inventory__slot + .gs-inventory__slot { opacity: 0.3; }

/* -- the empty card ------------------------------------------------------- */
/* Under the ghost row, 16 below it: a surface at the largest radius on the
   raised depth, which is the drawing's inset highlight over a 6px shelf to
   within the 1px depth.raised's 5px shelf allows. Padded 20 over 16, which is
   space.4 plus space.1. */
.gs-inventory[data-gs-empty] .gs-inventory__list {
  margin-block-end: var(--gs-space-4);
}

.gs-inventory__empty {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  margin: 0;
  padding: calc(var(--gs-space-4) + var(--gs-space-1)) var(--gs-space-4);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-xl);
  background: var(--gs-color-surface);
  box-shadow: var(--gs-depth-raised);
  color: var(--gs-color-ink);
  text-align: center;
}

/* The question mark in a dashed disc at the hero icon size. The mark is the
   display face at the stat size, 22px against the drawing's 26: no display
   token is 26px, and it is a token request in the report. */
.gs-inventory__glyph {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--gs-size-icon-hero);
  block-size: var(--gs-size-icon-hero);
  margin: 0 auto var(--gs-space-3);
  border: var(--gs-stroke-ui) dashed var(--gs-color-muted);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge);
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  line-height: 1;
  color: var(--gs-color-muted);
  /* Emphasis: it survives reduced motion, which is the only reason it is here
     rather than an animation. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* "Nothing yet": the figure face, uppercase. The drawing sets it at 16px and
   figure is 14, the nearest display token within the 2px the twin allows. */
.gs-inventory__empty-label {
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  line-height: 1.2;
  text-transform: uppercase;
}

/* The sentence: the interface face at the label size and the caption weight,
   which is the drawing's 13px/600 to within 1px; the body role is 17px and
   would not fit the card at a phone width. 6 above, the inset below. */
.gs-inventory__empty-detail {
  margin: var(--gs-inventory-gap-tight) 0 var(--gs-space-inset);
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-caption-font-weight);
  line-height: 1.4;
  color: var(--gs-color-ink-secondary);
}

/* The one action: a primary at the action height on the pressable depth, in
   the action face at the figure size, one property borrowed, because the
   drawing sets Play now at 14px and the 19px action face would fill the card.
   The drawing's control is 52px tall; size.action is 60 in arcade and the
   nearest, and a size.actionCompact is a token request in the report. */
.gs-inventory__commit {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  block-size: var(--gs-size-action);
  margin: 0;
  padding: 0 var(--gs-space-6);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  background: var(--gs-color-interactive);
  color: var(--gs-color-on-accent);
  box-shadow: var(--gs-depth-pressable);
  font-size: var(--gs-type-figure-font-size);
  line-height: 1;
  cursor: pointer;
}

/* The press: the face travels onto its shelf, the theme's own gesture. */
.gs-inventory__commit:active {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-pressable-pressed);
}

.gs-inventory__commit:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: var(--gs-space-1);
}
